#include <vector>
#include <deque>
#include <algorithm>

class Solution {
public:
    int minThresholdPath(int n, std::vector<std::vector<int>>& edges, int source, int target, int k) {
        std::vector<std::vector<std::pair<int, int>>> g(n);
        std::vector<int> weights = {0};
        for (const auto& e : edges) {
            g[e[0]].push_back({e[1], e[2]});
            g[e[1]].push_back({e[0], e[2]});
            weights.push_back(e[2]);
        }
        std::sort(weights.begin(), weights.end());
        weights.erase(std::unique(weights.begin(), weights.end()), weights.end());

        auto canReach = [&](int threshold) -> bool {
            std::vector<int> dist(n, 1e9);
            dist[source] = 0;
            std::deque<int> q;
            q.push_back(source);
            while (!q.empty()) {
                int u = q.front();
                q.pop_front();
                if (u == target) return dist[u] <= k;
                int d = dist[u];
                for (const auto& [v, w] : g[u]) {
                    int cost = (w > threshold) ? 1 : 0;
                    if (d + cost < dist[v] && d + cost <= k) {
                        dist[v] = d + cost;
                        if (cost == 0) q.push_front(v);
                        else q.push_back(v);
                    }
                }
            }
            return dist[target] <= k;
        };

        if (!canReach(weights.back())) return -1;
        int low = 0, high = weights.size() - 1, ans = weights.back();
        while (low <= high) {
            int mid = (low + high) / 2;
            if (canReach(weights[mid])) {
                ans = weights[mid];
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minThresholdPath(int n, int[][] edges, int source, int target, int k) {
        List<List<int[]>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        TreeSet<Integer> weightSet = new TreeSet<>();
        weightSet.add(0);
        for (int[] e : edges) {
            g.get(e[0]).add(new int[]{e[1], e[2]});
            g.get(e[1]).add(new int[]{e[0], e[2]});
            weightSet.add(e[2]);
        }
        List<Integer> weights = new ArrayList<>(weightSet);

        if (!canReach(n, g, source, target, k, weights.get(weights.size() - 1))) return -1;
        int low = 0, high = weights.size() - 1, ans = weights.get(weights.size() - 1);
        while (low <= high) {
            int mid = (low + high) / 2;
            if (canReach(n, g, source, target, k, weights.get(mid))) {
                ans = weights.get(mid);
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private boolean canReach(int n, List<List<int[]>> g, int source, int target, int k, int threshold) {
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[source] = 0;
        Deque<Integer> q = new ArrayDeque<>();
        q.add(source);
        while (!q.isEmpty()) {
            int u = q.pollFirst();
            if (u == target) return dist[u] <= k;
            int d = dist[u];
            for (int[] edge : g.get(u)) {
                int v = edge[0], w = edge[1];
                int cost = (w > threshold) ? 1 : 0;
                if (d + cost < dist[v] && d + cost <= k) {
                    dist[v] = d + cost;
                    if (cost == 0) q.addFirst(v);
                    else q.addLast(v);
                }
            }
        }
        return dist[target] <= k;
    }
}

function minThresholdPath(n, edges, source, target, k) {
    const g = Array.from({ length: n }, () => []);
    const weightSet = new Set([0]);
    for (const [u, v, w] of edges) {
        g[u].push([v, w]);
        g[v].push([u, w]);
        weightSet.add(w);
    }
    const weights = Array.from(weightSet).sort((a, b) => a - b);

    function canReach(threshold) {
        const dist = new Array(n).fill(Infinity);
        dist[source] = 0;
        const q = [source];
        let head = 0;
        while (head < q.length) {
            const u = q[head++];
            if (u === target) return dist[u] <= k;
            const d = dist[u];
            for (const [v, w] of g[u]) {
                const cost = (w > threshold) ? 1 : 0;
                if (d + cost < dist[v] && d + cost <= k) {
                    dist[v] = d + cost;
                    if (cost === 0) {
                        q.splice(head, 0, v);
                    } else {
                        q.push(v);
                    }
                }
            }
        }
        return dist[target] <= k;
    }

    if (!canReach(weights[weights.length - 1])) return -1;
    let low = 0, high = weights.length - 1, ans = weights[weights.length - 1];
    while (low <= high) {
        const mid = (low + high) >> 1;
        if (canReach(weights[mid])) {
            ans = weights[mid];
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
}
